 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using Contoso.Orders;

 namespace Contoso.Orders.Tests;

 [TestClass]
 public sealed class OrderServiceTests
 {
     private readonly OrderService _sut;

     public OrderServiceTests()
     {
         _sut = new OrderService();
     }

     private static List<OrderItem> CreateItems(int count = 1) =>
         Enumerable.Range(1, count).Select(i => new OrderItem
         {
             ProductName = $"Product {i}",
             Price = 10.00m * i,
             Quantity = i
         }).ToList();

     #region CreateOrder - Happy Path

     [TestMethod]
     public void CreateOrder_WithValidInputs_ReturnsOrderWithCorrectCustomerId()
     {
         // Arrange
         var items = CreateItems();

         // Act
         var order = _sut.CreateOrder("customer-1", items);

         // Assert
         Assert.AreEqual("customer-1", order.CustomerId);
     }

     [TestMethod]
     public void CreateOrder_WithValidInputs_ReturnsOrderWithNonEmptyId()
     {
         // Arrange
         var items = CreateItems();

         // Act
         var order = _sut.CreateOrder("customer-1", items);

         // Assert
         Assert.IsNotNull(order.Id);
         Assert.AreNotEqual(string.Empty, order.Id);
     }

     [TestMethod]
     public void CreateOrder_WithValidInputs_SetsCreatedAtToRecentTime()
     {
         // Arrange
         var items = CreateItems();
         var before = DateTime.UtcNow;

         // Act
         var order = _sut.CreateOrder("customer-1", items);

         // Assert
         var after = DateTime.UtcNow;
         Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
     }

     [TestMethod]
     public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
     {
         // Arrange
         var items = new List<OrderItem>
         {
             new() { ProductName = "Widget", Price = 25.50m, Quantity = 3 }
         };

         // Act
         var order = _sut.CreateOrder("customer-1", items);

         // Assert
         Assert.AreEqual(76.50m, order.Total);
     }

     [TestMethod]
     public void CreateOrder_WithMultipleItems_SumsAllItemTotals()
     {
         // Arrange
         var items = new List<OrderItem>
         {
             new() { ProductName = "A", Price = 10.00m, Quantity = 2 },  // 20
             new() { ProductName = "B", Price = 5.00m, Quantity = 4 },   // 20
             new() { ProductName = "C", Price = 3.00m, Quantity = 1 }    //  3
         };

         // Act
         var order = _sut.CreateOrder("customer-1", items);

         // Assert
         Assert.AreEqual(43.00m, order.Total);
     }

     [TestMethod]
     public void CreateOrder_WithValidInputs_StoresItemsOnOrder()
     {
         // Arrange
         var items = CreateItems(3);

         // Act
         var order = _sut.CreateOrder("customer-1", items);

         // Assert
         Assert.HasCount(3, order.Items);
     }

     #endregion

